function setPlayerName(value){playerName=String(value||'').slice(0,24);const stored=playerName.trim();if(stored)localStorage.setItem(PLAYER_NAME_KEY,stored);else localStorage.removeItem(PLAYER_NAME_KEY);resetActors();syncPlayerName()}
function renderOpponentCard(){const card=$('#opponent-card');if(!card)return;card.dataset.preset=opponentProfile.presetId;card.dataset.character=opponentProfile.baseCharacterId;$('#opponent-name').textContent=opponentProfile.name.toUpperCase();$('#opponent-preset').textContent=opponentProfile.presetLabel;$('#opponent-description').textContent=opponentProfile.description;$('#opponent-seed').textContent=`SEED ${String(opponentSeed).slice(0,12)}`}
