function toggleAppearance(part){const category=categoryForPart(part),options=variantOptions(currentCharacterId,category);if(options.length){activeAppearanceCategory=category;syncAppearancePanel();return}if(!APPEARANCE_LAYERS.includes(part))return;if(SHARED_APPEARANCE_LAYERS.includes(part))sharedAppearance={...sharedAppearance,[part]:!sharedAppearance[part]};else if(CHARACTER_OWNED_LAYERS.includes(part))ownedAppearance={...ownedAppearance,[currentCharacterId]:{...ownedAppearance[currentCharacterId],[part]:!ownedAppearance[currentCharacterId][part]}};commitAppearanceChange()}
function selectAppearanceVariant(category,value){const key=variantKey(category),options=variantOptions(currentCharacterId,category);if(!key||!options.length)return;const next=value&&options.includes(value)?value:null;if(SHARED_APPEARANCE_CATEGORIES.includes(category))sharedAppearance={...sharedAppearance,[key]:next};else ownedAppearance={...ownedAppearance,[currentCharacterId]:{...ownedAppearance[currentCharacterId],[key]:next}};commitAppearanceChange()}
function resetAppearance(){sharedAppearance={hat:false,glasses:false,beard:false,accessory:false,...EMPTY_SHARED_VARIANTS()};ownedAppearance={...ownedAppearance,[currentCharacterId]:{outfit:true,shoes:true,...EMPTY_OWNED_VARIANTS()}};appearanceColors={...appearanceColors,[currentCharacterId]:EMPTY_COLORS()};commitAppearanceChange()}
async function chooseCharacter(id){if(id===currentCharacterId)return;currentCharacterId=id;sanitizeVariantSelections();await remountPlayerCharacter()}

function familyLabel(type){return NODE_SPECS[type]?.family||'NODE'}
function brainFamilyHuman(type){const family=familyLabel(type);if(family==='STATE')return 'ЧТО Я ЧУВСТВУ';if(family==='IMPULSE')return 'ЧЕГО Я ХОЧУ';if(family==='REACTION')return 'ЧТО Я ДЕЛАЮ';if(family==='CONTROL')return 'КАК ИДЁТ ДАЛЬШЕ';if(family==='ABILITY')return 'ЧТО Я УМЕЮ';return family}
function title(type){return NODE_SPECS[type]?.title||type}
function nodeValue(n){const f=familyLabel(n.type);if(f==='IMPULSE')return `W${n.p?.weight||1}`;if(n.type==='repeat')return `×${n.p?.count||1}`;if(f==='STATE')return `+${n.p?.delta??1}`;if(n.type==='ifbrain')return `>${n.p?.threshold||70}`;return ''}
function nodeSubtitle(n){return NODE_SPECS[n.type]?.description||familyLabel(n.type)}
function nodeOutgoingLabels(id){return outgoing(currentBrainGraph,id).map(edge=>currentBrainGraph.nodes.find(n=>n.id===edge.to)).filter(Boolean).map(n=>title(n.type))}
function nodeRouteLabel(n){const labels=[...new Set(nodeOutgoingLabels(n.id))];return labels.length?`→ ${labels.join(' · ')}`:''}
function brainControl(n){const f=familyLabel(n?.type);if(f==='IMPULSE')return {key:'weight',min:1,max:5,step:1,label:'СИЛА ИМПУЛЬСА',format:v=>`W${v}`};if(n?.type==='repeat')return {key:'count',min:1,max:5,step:1,label:'СКОЛЬКО РАЗ',format:v=>`×${v}`};if(f==='STATE')return {key:'delta',min:1,max:5,step:1,label:'ИЗМЕНЕНИЕ ПАМЯТИ',format:v=>`+${v}`};if(n?.type==='ifbrain')return {key:'threshold',min:20,max:100,step:10,label:'ПОРОГ BRAIN',format:v=>`>${v}`};return null}
function brainNodeLocked(n){return Boolean(replayMode&&replayTargetNodeId&&n.id!==replayTargetNodeId)}
function currentValidation(){return brainValidation(currentBrainGraph,CRITICISM_IDEA_SCENARIO.openingTrigger)}
let brainEdgeSerial=0,brainControlSheet=null;
function markBrainEdgeKinds(graph){const order=graph.nodes.map(n=>n.id),index=new Map(order.map((id,i)=>[id,i]));graph.edges=graph.edges.map(edge=>{if(edge.uiKind)return edge;const a=index.get(edge.from),b=index.get(edge.to);return {...edge,uiKind:Number.isInteger(a)&&Number.isInteger(b)&&b===a+1?'primary':'extra'}});return graph}
function primaryEdgeId(from,to){return `brain-primary-${from}-${to}-${++brainEdgeSerial}`}
function groupBrainNodes(){const triggers=currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER'),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER');currentBrainGraph.nodes=[...triggers,...body]}
function rebuildBrainSequence(){
  groupBrainNodes();markBrainEdgeKinds(currentBrainGraph);
  const triggers=currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER'),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER');
  const triggerIds=new Set(triggers.map(n=>n.id));
  const preserved=currentBrainGraph.edges.filter(e=>triggerIds.has(e.from)||e.uiManual||e.uiKind==='extra').map(e=>({...e,uiManual:e.uiManual||triggerIds.has(e.from)}));
  const byKey=new Map(preserved.map(e=>[`${e.from}->${e.to}`,e])),primary=[];
  for(let i=0;i<body.length-1;i++){const from=body[i],to=body[i+1],key=`${from.id}->${to.id}`;if(byKey.has(key))continue;const working={...currentBrainGraph,edges:[...preserved,...primary]};if(canConnectNodes(working,from,to))primary.push({id:primaryEdgeId(from.id,to.id),from:from.id,to:to.id,uiKind:'primary'})}
  if(triggers.length===1&&body.length&&!preserved.some(e=>e.from===triggers[0].id)){const from=triggers[0],to=body[0],working={...currentBrainGraph,edges:[...preserved,...primary]};if(canConnectNodes(working,from,to))preserved.push({id:primaryEdgeId(from.id,to.id),from:from.id,to:to.id,uiKind:'extra',uiManual:true})}
  currentBrainGraph.edges=[...preserved,...primary];currentBrainGraph.nodes.forEach((node,i)=>{node.ui={...(node.ui||{}),x:0,y:i*82}})
}
function normalizeBrainStack(){markBrainEdgeKinds(currentBrainGraph);currentBrainGraph.nodes.forEach((node,i)=>{node.ui={...(node.ui||{}),x:0,y:i*82}})}
function renderBrainPresets(){const host=$('#brain-presets');if(!host)return;host.hidden=replayMode;host.innerHTML=BRAIN_PRESETS.map(p=>`<button type="button" data-brain-preset="${p.id}" class="${activeBrainPresetId===p.id?'active':''}">${p.label}</button>`).join('')+`<button type="button" data-brain-preset="custom" class="${activeBrainPresetId==='custom'?'active':''}">СОБРАТЬ СВОЮ КАТАСТРОФУ</button>`;host.querySelectorAll('[data-brain-preset]').forEach(b=>b.addEventListener('click',()=>applyBrainPreset(b.dataset.brainPreset)))}
function applyBrainPreset(id){if(replayMode)return;const p=brainPreset(id);currentBrainGraph=cloneBrainGraph(p?.graph||BLANK_BRAIN);normalizeBrainStack();activeBrainPresetId=p?.id||'custom';activeBrainNodeId=null;brainConnectFromId=null;activeBrainTriggerId=null;brainTriggerHubOpen=!p;closeBrainControlSheet();renderBrain()}
function brainActionWidth(n){return brainControl(n)?184:128}
function brainNodeHtml(n){const selected=n.id===activeBrainNodeId,source=n.id===brainConnectFromId,locked=brainNodeLocked(n),validTargets=brainConnectFromId?compatibleBrainTargets(currentBrainGraph,brainConnectFromId):[],compatible=validTargets.includes(n.id),control=brainControl(n),related=Boolean(activeBrainNodeId&&activeBrainNodeId!==n.id&&currentBrainGraph.edges.some(e=>(e.from===activeBrainNodeId&&e.to===n.id)||(e.to===activeBrainNodeId&&e.from===n.id)));return `<article class="brain-stack-node ${selected?'open connection-focus':''} ${related?'connection-related':''} ${source?'connection-source':''} ${compatible?'connection-target':''} ${locked?'locked':''}" data-brain-node-wrap="${n.id}" style="--brain-actions-w:${brainActionWidth(n)}px"><div class="brain-stack-card"><div class="brain-stack-actions"><button type="button" class="brain-stack-action brain-connect-source-button ${source?'active':''}" data-brain-connect="${n.id}" aria-label="Связать"><img src="./assets/ui/brain-connect.svg" alt=""></button>${control?`<button type="button" class="brain-stack-action" data-brain-param="${n.id}">${nodeValue(n)}</button>`:''}<button type="button" class="brain-stack-action" data-brain-delete="${n.id}" aria-label="Удалить"><img src="./assets/ui/brain-trash.svg" alt=""></button></div><button type="button" class="brain-stack-main" data-brain-node="${n.id}" ${locked?'aria-disabled="true"':''}><span class="brain-stack-family">${brainFamilyHuman(n.type)}</span><strong class="brain-stack-title">${title(n.type)}</strong><span class="brain-stack-subtitle">${nodeSubtitle(n)}</span>${nodeRouteLabel(n)?`<span class="brain-stack-route">${nodeRouteLabel(n)}</span>`:''}</button>${control?`<span class="brain-stack-value">${nodeValue(n)}</span>`:''}<button type="button" class="brain-stack-drag" data-brain-drag="${n.id}" aria-label="Перетянуть"><span class="brain-stack-handle"></span></button><button type="button" class="brain-stack-connect-target" data-brain-target="${n.id}">СОЕДИНИТЬ</button></div></article>`}
function brainEdgeRoutes(){const order=currentBrainGraph.nodes.map(n=>n.id),index=new Map(order.map((id,i)=>[id,i]));const routes=currentBrainGraph.edges.map((edge,orderIndex)=>{const fromIndex=index.get(edge.from),toIndex=index.get(edge.to);return {...edge,orderIndex,fromIndex,toIndex,a:Math.min(fromIndex,toIndex),b:Math.max(fromIndex,toIndex),kind:edge.uiKind==='extra'?'extra':'primary'}}).filter(e=>Number.isInteger(e.fromIndex)&&Number.isInteger(e.toIndex));const extras=routes.filter(e=>e.kind==='extra').sort((a,b)=>(a.a-b.a)||(a.b-b.b)||(a.orderIndex-b.orderIndex));const lanes=[];extras.forEach(edge=>{let lane=0;while(lanes[lane]?.some(other=>Math.max(edge.a,other.a)<Math.min(edge.b,other.b)))lane++;(lanes[lane]??=[]).push(edge);edge.lane=lane});return routes}
function drawBrainEdges(){const host=$('#brain-graph'),svg=host?.querySelector('.brain-stack-links');if(!host||!svg)return;const box=host.getBoundingClientRect(),byId=Object.fromEntries($$('#brain-graph [data-brain-node-wrap]').map(el=>[el.dataset.brainNodeWrap,el]));const routes=brainEdgeRoutes(),outgoing=new Map(),incoming=new Map();routes.forEach(edge=>{(outgoing.get(edge.from)??outgoing.set(edge.from,[]).get(edge.from)).push(edge);(incoming.get(edge.to)??incoming.set(edge.to,[]).get(edge.to)).push(edge)});outgoing.forEach(list=>list.sort((a,b)=>(a.kind!==b.kind?(a.kind==='primary'?-1:1):a.toIndex-b.toIndex)));incoming.forEach(list=>list.sort((a,b)=>(a.kind!==b.kind?(a.kind==='primary'?-1:1):a.fromIndex-b.fromIndex)));svg.setAttribute('viewBox',`0 0 ${host.clientWidth} ${Math.max(host.scrollHeight,host.clientHeight)}`);svg.innerHTML=routes.map(edge=>{const from=byId[edge.from],to=byId[edge.to];if(!from||!to)return '';const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),out=outgoing.get(edge.from)||[edge],inc=incoming.get(edge.to)||[edge],slot=9,y1=a.top+a.height/2-box.top+(out.indexOf(edge)-(out.length-1)/2)*slot,y2=b.top+b.height/2-box.top+(inc.indexOf(edge)-(inc.length-1)/2)*slot,cardX=a.left-box.left,laneX=edge.kind==='primary'?Math.max(8,cardX-14):Math.max(8,cardX-32-(edge.lane||0)*13);const focus=Boolean(activeBrainNodeId&&(edge.from===activeBrainNodeId||edge.to===activeBrainNodeId));return `<path class="brain-stack-edge ${edge.kind==='extra'?'extra':''} ${focus?'focus':''}" data-edge="${edge.id}" d="M ${cardX} ${y1} H ${laneX} V ${y2} H ${cardX}"></path>`}).join('')}
function reorderBrainNode(id,targetIndex){const node=currentBrainGraph.nodes.find(n=>n.id===id);if(!node||familyOf(node)==='TRIGGER')return;const triggers=currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER'),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER'),from=body.findIndex(n=>n.id===id);if(from<0||targetIndex===from)return;const [moved]=body.splice(from,1),bounded=Math.max(0,Math.min(body.length,targetIndex));body.splice(bounded,0,moved);currentBrainGraph.nodes=[...triggers,...body];rebuildBrainSequence();activeBrainPresetId='custom'}
function bindBrainStackDrag(){$$('#brain-graph [data-brain-drag]').forEach(handle=>{let start=null;handle.addEventListener('pointerdown',e=>{const id=handle.dataset.brainDrag,node=currentBrainGraph.nodes.find(n=>n.id===id);if(replayMode||brainNodeLocked(node))return;const wrap=handle.closest('.brain-stack-node');start={id,y:e.clientY,index:currentBrainGraph.nodes.findIndex(n=>n.id===id),wrap};handle.setPointerCapture?.(e.pointerId);e.preventDefault()});handle.addEventListener('pointermove',e=>{if(!start)return;start.wrap.style.transform=`translateY(${e.clientY-start.y}px)`;requestAnimationFrame(drawBrainEdges)});handle.addEventListener('pointerup',e=>{if(!start)return;const wraps=$$('#brain-graph .brain-stack-node').filter(w=>w!==start.wrap);let target=wraps.filter(w=>e.clientY>w.getBoundingClientRect().top+w.getBoundingClientRect().height/2).length;reorderBrainNode(start.id,target);start=null;renderBrain()});handle.addEventListener('pointercancel',()=>{if(start){start.wrap.style.transform='';start=null;renderBrainCanvas()}})})}
function selectBrainNode(id){const node=currentBrainGraph.nodes.find(n=>n.id===id);if(!node||brainNodeLocked(node))return;brainConnectFromId=null;activeBrainNodeId=activeBrainNodeId===id?null:id;renderBrainCanvas();renderBrainStatus()}
function beginBrainConnection(id){if(replayMode)return;const same=brainConnectFromId===id,node=fromBrainNode(id);brainConnectFromId=same?null:id;activeBrainNodeId=same?null:id;if(node&&familyOf(node)==='TRIGGER'){activeBrainTriggerId=same?null:id;brainTriggerHubOpen=true}renderBrainCanvas();renderBrainStatus()}
