function deleteBrainNode(id){if(replayMode)return;const node=fromBrainNode(id);if(!node||familyOf(node)==='TRIGGER')return;removeBrainNode(currentBrainGraph,id);activeBrainNodeId=null;brainConnectFromId=null;activeBrainPresetId='custom';rebuildBrainSequence();renderBrain()}
function closeBrainControlSheet(){brainControlSheet?.remove();brainControlSheet=null}
function showBrainControlSheet(id){const node=currentBrainGraph.nodes.find(n=>n.id===id),control=brainControl(node);if(!node||!control||brainNodeLocked(node))return;closeBrainControlSheet();const current=Number(node.p?.[control.key]??control.min),sheet=document.createElement('div');sheet.className='brain-control-backdrop';const ticks=Math.max(2,Math.round((control.max-control.min)/(control.step||1))+1);sheet.innerHTML=`<section class="brain-control-sheet"><div class="brain-control-sheet__handle"></div><div class="brain-control-sheet__head"><b>${title(node.type)}</b><span>${control.label}</span></div><div class="brain-control-range"><div class="brain-control-range__inner" role="slider" tabindex="0" aria-valuemin="${control.min}" aria-valuemax="${control.max}" aria-valuenow="${current}"><div class="brain-control-range__track"></div><div class="brain-control-range__ticks">${Array.from({length:Math.min(ticks,9)},()=>'<i></i>').join('')}</div><button type="button" class="brain-control-range__thumb">${current}</button></div></div><div class="brain-control-range__note">${nodeSubtitle(node)}</div></section>`;document.body.appendChild(sheet);brainControlSheet=sheet;const range=sheet.querySelector('.brain-control-range__inner'),thumb=sheet.querySelector('.brain-control-range__thumb'),snap=value=>Math.max(control.min,Math.min(control.max,control.min+Math.round((value-control.min)/(control.step||1))*(control.step||1))),place=value=>{const v=snap(value),pct=(v-control.min)/(control.max-control.min||1),radius=34,usable=Math.max(0,range.clientWidth-radius*2),x=radius+pct*usable;thumb.style.left=`${x}px`;thumb.textContent=String(v);range.setAttribute('aria-valuenow',String(v));node.p[control.key]=v;activeBrainPresetId='custom'},fromX=x=>{const r=range.getBoundingClientRect(),radius=34,left=r.left+radius,right=r.right-radius,pct=(Math.max(left,Math.min(right,x))-left)/(right-left||1);return control.min+pct*(control.max-control.min)};place(current);let dragging=false;thumb.addEventListener('pointerdown',e=>{dragging=true;thumb.setPointerCapture?.(e.pointerId);e.preventDefault()});thumb.addEventListener('pointermove',e=>{if(!dragging)return;place(fromX(e.clientX));renderBrainCanvas()});thumb.addEventListener('pointerup',()=>{dragging=false});thumb.addEventListener('pointercancel',()=>{dragging=false});range.addEventListener('pointerdown',e=>{if(e.target===thumb)return;place(fromX(e.clientX));renderBrainCanvas()});range.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();place(Number(node.p[control.key])+(e.key==='ArrowRight'?1:-1)*(control.step||1));renderBrainCanvas()});sheet.addEventListener('click',e=>{if(e.target===sheet)closeBrainControlSheet()})}
function renderBrainStatus(){const host=$('#brain-validation');if(!host)return;const v=currentValidation();host.dataset.code=v.code;host.classList.toggle('ready',v.runnable);host.textContent=brainConnectFromId?`СВЯЗЬ: «${title(currentBrainGraph.nodes.find(n=>n.id===brainConnectFromId)?.type)}» → ВЫБЕРИ ДОПУСТИМЫЙ УЗЕЛ.`:(v.runnable?'ГОТОВ. ГРАФ ДОХОДИТ ДО РЕАКЦИИ.':v.detail);$('#to-setup').disabled=!v.runnable}
function brainTriggerNodes(){return currentBrainGraph.nodes.filter(n=>familyOf(n)==='TRIGGER')}
function triggerRoute(triggerId){const seen=new Set(),stack=[triggerId];while(stack.length){const id=stack.pop();if(seen.has(id))continue;seen.add(id);for(const edge of outgoing(currentBrainGraph,id))stack.push(edge.to)}return seen}
function triggerDestination(node){const labels=outgoing(currentBrainGraph,node.id).map(edge=>currentBrainGraph.nodes.find(n=>n.id===edge.to)).filter(Boolean).map(n=>title(n.type));return labels.length?[...new Set(labels)].join(' · '):'НЕ ПОДКЛЮЧЕНО'}
function brainReadableRole(node){const family=familyOf(node);if(family==='TRIGGER')return 'КОГДА';if(family==='STATE')return 'Я ЧУВСТВУ';if(family==='IMPULSE')return 'Я ХОЧУ';if(family==='REACTION')return 'Я ДЕЛАЮ';if(family==='CONTROL')return 'ДАЛЬШЕ';if(family==='ABILITY')return 'Я МОГУ';return 'УЗЕЛ'}
function brainReadableRouteNodes(){const triggers=brainTriggerNodes(),wired=triggers.filter(n=>outgoing(currentBrainGraph,n.id).length>0);let start=activeBrainTriggerId&&wired.find(n=>n.id===activeBrainTriggerId);if(!start)start=wired.find(n=>n.type===CRITICISM_IDEA_SCENARIO.openingTrigger)||wired[0];if(!start)return [];const order=new Map(currentBrainGraph.nodes.map((n,i)=>[n.id,i])),seen=new Set(),nodes=[];let current=start;while(current&&!seen.has(current.id)&&nodes.length<8){seen.add(current.id);nodes.push(current);const edges=outgoing(currentBrainGraph,current.id).slice().sort((a,b)=>((a.uiKind==='primary'?0:1)-(b.uiKind==='primary'?0:1))||((order.get(a.to)??999)-(order.get(b.to)??999)));current=edges.length?fromBrainNode(edges[0].to):null}return nodes}
function brainReadableAlternatives(node,nextId){const seen=new Set();return outgoing(currentBrainGraph,node.id).filter(edge=>edge.to!==nextId).map(edge=>fromBrainNode(edge.to)).filter(Boolean).filter(target=>{if(seen.has(target.id))return false;seen.add(target.id);return true})}
function brainReadableRouteHtml(){const nodes=brainReadableRouteNodes();if(!nodes.length)return `<div class="brain-readable-route empty" data-brain-readable-route><small>КАК ЭТО СРАБОТАЕТ</small><p>ПОДКЛЮЧИ ХОТЯ БЫ ОДНУ РЕАКЦИЮ СВЕРХУ — И ЗДЕСЬ ПОЯВИТСЯ ПОВЕДЕНЧЕСКАЯ ЦЕПОЧКА.</p></div>`;return `<div class="brain-readable-route" data-brain-readable-route><small>КАК ЭТО СРАБОТАЕТ</small><div class="brain-readable-route__flow">${nodes.map((node,i)=>{const next=nodes[i+1]||null,alts=brainReadableAlternatives(node,next?.id);return `<div class="brain-readable-cluster"><button type="button" data-readable-node="${node.id}" class="brain-readable-step ${node.id===activeBrainTriggerId||node.id===activeBrainNodeId?'active':''}"><span>${brainReadableRole(node)}</span><strong>${title(node.type)}</strong></button>${alts.length?`<div class="brain-readable-alts"><span>ИЛИ</span>${alts.map(alt=>`<button type="button" class="brain-readable-alt ${alt.id===activeBrainNodeId||alt.id===activeBrainTriggerId?'active':''}" data-readable-node="${alt.id}">${title(alt.type)}</button>`).join('')}</div>`:''}</div>${i<nodes.length-1?'<b class="brain-readable-arrow" aria-hidden="true">→</b>':''}`}).join('')}</div></div>`}
function triggerHubHtml(){const triggers=brainTriggerNodes(),active=activeBrainTriggerId&&triggers.some(n=>n.id===activeBrainTriggerId)?activeBrainTriggerId:null,configured=triggers.filter(n=>outgoing(currentBrainGraph,n.id).length>0).length;const chips=triggers.map(n=>{const wired=outgoing(currentBrainGraph,n.id).length>0;return `<button type="button" class="brain-trigger-chip ${wired?'wired':'unwired'} ${n.id===active?'active':''}" data-trigger-select="${n.id}">${title(n.type)}</button>`}).join('');const rows=triggers.map(n=>{const source=n.id===brainConnectFromId,hasRoutes=outgoing(currentBrainGraph,n.id).length>0;return `<div class="brain-trigger-row ${n.id===active?'active':''} ${source?'connection-source':''}" data-trigger-row="${n.id}"><button type="button" class="brain-trigger-row__main" data-trigger-select="${n.id}"><strong>${title(n.type)}</strong><span>${nodeSubtitle(n)}</span><em>→ ${triggerDestination(n)}</em></button>${replayMode?'':`<div class="brain-trigger-row__actions"><button type="button" class="brain-connect-source-button ${source?'active':''}" data-trigger-connect="${n.id}" aria-label="Связать ${title(n.type)}"><img src="./assets/ui/brain-connect.svg" alt=""><span>СВЯЗАТЬ</span></button><button type="button" class="brain-trigger-disconnect" data-trigger-disconnect="${n.id}" ${hasRoutes?'':'disabled'}>ОТКЛЮЧИТЬ</button></div>`}</div>`}).join('');return `<section class="brain-trigger-hub ${brainTriggerHubOpen?'open':''}" data-trigger-hub><button type="button" class="brain-trigger-hub__head" data-trigger-hub-toggle aria-expanded="${brainTriggerHubOpen}"><span><small>ВХОДЫ</small><strong>${triggers.length?'НА ЧТО Я РЕАГИРУЮ':'НА ЧТО ТЫ РЕАГИРУЕШЬ?'}</strong></span><b>${configured}/${triggers.length}</b><i>${brainTriggerHubOpen?'−':'+'}</i></button>${triggers.length?`<div class="brain-trigger-chips">${chips}</div>`:'<p class="brain-trigger-empty">СИСТЕМНЫЕ ВХОДЫ НЕ НАЙДЕНЫ.</p>'}<div class="brain-trigger-hub__body">${rows}</div></section>`}
function disconnectTriggerRoutes(id){if(replayMode)return;const node=fromBrainNode(id);if(!node||familyOf(node)!=='TRIGGER')return;currentBrainGraph.edges=currentBrainGraph.edges.filter(edge=>edge.from!==id);if(brainConnectFromId===id)brainConnectFromId=null;activeBrainTriggerId=id;activeBrainNodeId=null;activeBrainPresetId='custom';renderBrainCanvas();renderBrainStatus()}
function bindTriggerHub(){const host=$('#brain-graph');host?.querySelector('[data-trigger-hub-toggle]')?.addEventListener('click',()=>{brainTriggerHubOpen=!brainTriggerHubOpen;renderBrainCanvas()});host?.querySelectorAll('[data-trigger-select]').forEach(button=>button.addEventListener('click',()=>{activeBrainTriggerId=activeBrainTriggerId===button.dataset.triggerSelect?null:button.dataset.triggerSelect;brainTriggerHubOpen=true;brainConnectFromId=null;activeBrainNodeId=null;renderBrainCanvas();renderBrainStatus()}));host?.querySelectorAll('[data-trigger-connect]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();beginBrainConnection(button.dataset.triggerConnect)}));host?.querySelectorAll('[data-trigger-disconnect]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();disconnectTriggerRoutes(button.dataset.triggerDisconnect)}))}
function projectedBrainNodeHtml(n,route){const html=brainNodeHtml(n);if(!activeBrainTriggerId)return html;return html.replace('brain-stack-node ',`brain-stack-node ${route.has(n.id)?'route-active':'route-muted'} `)}
function renderBrainCanvas(){const host=$('#brain-graph');if(!host)return;groupBrainNodes();normalizeBrainStack();const route=activeBrainTriggerId?triggerRoute(activeBrainTriggerId):new Set(),body=currentBrainGraph.nodes.filter(n=>familyOf(n)!=='TRIGGER');host.dataset.edgeCount=String(currentBrainGraph.edges.length);host.dataset.connectFrom=brainConnectFromId||'';host.dataset.activeTrigger=activeBrainTriggerId||'';host.innerHTML=`${triggerHubHtml()}<section class="brain-behavior-block" data-behavior-block><div class="brain-behavior-head"><small>ВНУТРИ МОЗГА</small><strong>ЧТО Я ДЕЛАЮ, КОГДА ЭТО СЛУЧИЛОСЬ</strong><p>Читается сверху вниз: что я чувствую → чего хочу → что делаю → что происходит дальше.</p></div>${brainReadableRouteHtml()}<svg class="brain-stack-links" aria-hidden="true"></svg><div class="brain-stack-list">${body.map(n=>projectedBrainNodeHtml(n,route)).join('')}</div></section>`;bindTriggerHub();host.querySelectorAll('[data-readable-node]').forEach(button=>button.addEventListener('click',()=>{const node=fromBrainNode(button.dataset.readableNode);if(!node)return;if(familyOf(node)==='TRIGGER'){activeBrainTriggerId=node.id;brainTriggerHubOpen=true;brainConnectFromId=null;activeBrainNodeId=null;renderBrainCanvas();renderBrainStatus()}else selectBrainNode(node.id)}));host.querySelectorAll('[data-brain-node]').forEach(button=>button.addEventListener('click',()=>selectBrainNode(button.dataset.brainNode)));host.querySelectorAll('[data-brain-connect]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();beginBrainConnection(button.dataset.brainConnect)}));host.querySelectorAll('[data-brain-param]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();showBrainControlSheet(button.dataset.brainParam)}));host.querySelectorAll('[data-brain-delete]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();deleteBrainNode(button.dataset.brainDelete)}));host.querySelectorAll('[data-brain-target]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();finishBrainConnection(button.dataset.brainTarget)}));bindBrainStackDrag();requestAnimationFrame(drawBrainEdges)}
function libraryNodeValue(spec){const fake={type:spec.type,p:{...(spec.defaults||{})}};return nodeValue(fake)}
function libraryNodeHtml(spec,family){const system=family==='TRIGGER',value=libraryNodeValue(spec);return `<button type="button" class="brain-library-node ${system?'system-trigger':''}" ${system?`data-open-trigger-type="${spec.type}"`:`data-add-brain-node="${spec.type}"`} data-node-family="${family}"><span class="brain-library-node__family">${family.toLowerCase()}</span><strong class="brain-library-node__title">${spec.title}</strong><span class="brain-library-node__description">${nodeSubtitle({type:spec.type})}</span>${value?`<b class="brain-library-node__value">${value}</b>`:''}${system?'<em class="brain-library-node__system">НАСТРОИТЬ ВО ВХОДАХ</em>':''}</button>`}
function focusSystemTrigger(type){const node=brainTriggerNodes().find(n=>n.type===type);if(!node)return;hideOverlay();brainTriggerHubOpen=true;activeBrainTriggerId=node.id;brainConnectFromId=null;activeBrainNodeId=null;renderBrain();requestAnimationFrame(()=>document.querySelector('[data-trigger-hub]')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function showNodeLibrary(){if(replayMode)return;const families=BRAIN_FAMILY_ORDER.map(f=>({family:f,nodes:familyNodes(f).filter(n=>n.availableInSlice!==false)})).filter(group=>group.nodes.length);overlay.innerHTML=`<div class="overlay-card brain-library"><p class="kicker">БИБЛИОТЕКА</p><h3>ДОБАВИТЬ УЗЕЛ</h3><div class="brain-library-accordion">${families.map((group,i)=>`<section class="brain-library-section ${i===0?'open':''}" data-library-family="${group.family}"><button type="button" class="brain-library-section__head" data-library-toggle="${group.family}" aria-expanded="${i===0}"><strong>${group.family}</strong><b>${group.nodes.length}</b><i>${i===0?'−':'+'}</i></button><div class="brain-library-section__body">${group.nodes.map(spec=>libraryNodeHtml(spec,group.family)).join('')}</div></section>`).join('')}</div><button class="secondary-reset" id="close-overlay">ЗАКРЫТЬ</button></div>`;overlay.hidden=false;overlay.querySelectorAll('[data-library-toggle]').forEach(button=>button.addEventListener('click',()=>{const family=button.dataset.libraryToggle;overlay.querySelectorAll('.brain-library-section').forEach(section=>{const open=section.dataset.libraryFamily===family;section.classList.toggle('open',open);section.querySelector('[data-library-toggle]')?.setAttribute('aria-expanded',String(open));const icon=section.querySelector('.brain-library-section__head i');if(icon)icon.textContent=open?'−':'+'})}));overlay.querySelectorAll('[data-open-trigger-type]').forEach(button=>button.addEventListener('click',()=>focusSystemTrigger(button.dataset.openTriggerType)));overlay.querySelectorAll('[data-add-brain-node]').forEach(b=>b.addEventListener('click',()=>{const node=addBrainNode(currentBrainGraph,b.dataset.addBrainNode);activeBrainNodeId=node.id;activeBrainPresetId='custom';brainConnectFromId=null;rebuildBrainSequence();hideOverlay();renderBrain();requestAnimationFrame(()=>document.querySelector(`[data-brain-node-wrap="${CSS.escape(node.id)}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}))}));$('#close-overlay').onclick=hideOverlay}
function renderBrain(){closeBrainControlSheet();normalizeBrainStack();renderBrainPresets();renderBrainCanvas();renderBrainStatus();const add=$('#brain-add-node');if(add)add.hidden=replayMode}
function brainSnapshot(){return cloneBrainGraph(currentBrainGraph)}
function restoreBrainSnapshot(graph){currentBrainGraph=cloneBrainGraph(graph);ensureBrainPositions(currentBrainGraph);activeBrainNodeId=null;brainConnectFromId=null}

function metricRow(label,key){const a=controller?.encounter?.actors.A.state[key]??actors.A.state[key],b=controller?.encounter?.actors.B.state[key]??actors.B.state[key];const danger=(key==='brain'&&(a>=85||b>=85))||(key==='energy'&&(a<=25||b<=25))||(key==='contact'&&(a<=20||b<=20))||(key==='tension'&&(a>=85||b>=85));return `<div class="metric ${danger?'danger':''}"><label>${label}</label><span class="bar"><i style="width:${Math.max(0,Math.min(100,a))}%"></i></span><span class="n">${Math.round(a)}</span><span class="n">${Math.round(b)}</span><span class="bar"><i style="width:${Math.max(0,Math.min(100,b))}%"></i></span></div>`}
function renderTalk(){if(!controller?.encounter)return;const e=controller.encounter;$('#turn').textContent=e.turn;$('#actor-a-name').textContent=e.actors.A.name.toUpperCase();$('#actor-b-name').textContent=e.actors.B.name.toUpperCase();$('#metrics').innerHTML=metricRow('ENERGY','energy')+metricRow('BRAIN','brain')+metricRow('TENSION','tension')+metricRow('CONTACT','contact');const transcript=e.transcript.slice(-5);$('#dialogue').innerHTML=transcript.length?transcript.map(x=>`<div class="bubble ${x.actorId==='A'?'a':'b'}"><small>${e.actors[x.actorId].name.toUpperCase()}</small>${x.phrase||'…'}</div>`).join(''):'<p class="empty">Никто ещё ничего не сказал.</p>';$('#next-turn').textContent=mode==='auto'?(autoTimer?'PAUSE':'RESUME'):'NEXT TURN →'}
function renderDelta(trace){if(!trace)return $('#delta').textContent='';const d=trace.metricDeltas.self,memory=trace.memoryChanges||[];const parts=Object.entries(d).filter(([,v])=>v).map(([k,v])=>`${k.toUpperCase()} ${v>0?'+':''}${Number(v.toFixed?.(1)??v)}`);for(const m of [...memory].reverse())parts.unshift(`${String(m.key).toUpperCase()} ${m.before}→${m.after}`);const line=parts.join(' · ');$('#delta').textContent=line;setTimeout(()=>{if($('#delta').textContent===line)$('#delta').textContent=''},1100)}
function makeController(){const specA=characterSpec(currentCharacterId),specB=characterSpec(opponentProfile.baseCharacterId);const rendererA=new CharacterRenderer({side:'A',root:$('#actor-a'),rigFallback:specA.rigFallback}),rendererB=new CharacterRenderer({side:'B',root:$('#actor-b'),rigFallback:specB.rigFallback});controller=new VerticalSliceController({scenario:CRITICISM_IDEA_SCENARIO,actors,renderers:{A:rendererA,B:rendererB},onEvent:handleEvent})}
function handleEvent(evt){if(evt.type==='TURN'){renderDelta(evt.trace);renderTalk()}if(evt.type==='HOT_PATCH'){stopAuto();showHotPatch(evt.breakpoint)}if(evt.type==='RESULT'){stopAuto();showResult(evt.result)}if(evt.type==='PATCH'){hideOverlay();renderTalk();if(mode==='auto')startAuto()}}
function doNext(){if(!controller?.encounter||controller.encounter.result)return;const out=controller.next();renderTalk();if(out?.result)showResult(controller.result())}
function startAuto(){stopAuto();autoTimer=setInterval(()=>{if(controller?.encounter?.status==='HOT_PATCH'||controller?.encounter?.result)return stopAuto();doNext()},850);renderTalk()}
function stopAuto(){if(autoTimer){clearInterval(autoTimer);autoTimer=null}if(controller?.encounter)renderTalk()}
function hotPatchChainEdges(actor,ids){const set=new Set(ids||[]);return actor.brainGraph.edges.filter(e=>set.has(e.from)&&set.has(e.to))}
function hotPatchRewireOptions(actor,edge){if(!edge)return [];const graph=actor.brainGraph,from=graph.nodes.find(n=>n.id===edge.from),without={...graph,edges:graph.edges.filter(e=>e.id!==edge.id)};return graph.nodes.filter(candidate=>candidate.id!==edge.to&&canConnectNodes(without,from,candidate)).filter(candidate=>{const probe=cloneBrainGraph(graph),probeEdge=probe.edges.find(e=>e.id===edge.id);probeEdge.to=candidate.id;return brainValidation(probe,CRITICISM_IDEA_SCENARIO.openingTrigger).runnable})}
function showRewirePatch(bp,edge){const actor=controller.encounter.actors[bp.actorId],options=hotPatchRewireOptions(actor,edge);overlay.innerHTML=`<div class="overlay-card"><p class="kicker">HOT PATCH / СВЯЗЬ</p><h3>КУДА ПЕРЕНАПРАВИТЬ?</h3><p>${title(actor.brainGraph.nodes.find(n=>n.id===edge.from)?.type)} → …</p><div class="patch-grid">${options.map(n=>`<button data-rewire-target="${n.id}">→ ${title(n.type)}</button>`).join('')}<button data-rewire-back>НАЗАД</button></div></div>`;overlay.hidden=false;overlay.querySelectorAll('[data-rewire-target]').forEach(button=>button.addEventListener('click',()=>controller.patch({kind:'rewire',actorId:bp.actorId,edgeId:edge.id,toNodeId:button.dataset.rewireTarget})));overlay.querySelector('[data-rewire-back]')?.addEventListener('click',()=>showHotPatch(bp))}
function showHotPatch(bp){const actor=controller.encounter.actors[bp.actorId],ids=bp.nodeIds||[],chain=ids.map(id=>title(actor.brainGraph.nodes.find(n=>n.id===id)?.type)).join(' → '),repeat=ids.map(id=>actor.brainGraph.nodes.find(n=>n.id===id)).find(n=>n?.type==='repeat'),impulse=ids.map(id=>actor.brainGraph.nodes.find(n=>n.id===id)).find(n=>familyLabel(n?.type)==='IMPULSE'),chainEdges=hotPatchChainEdges(actor,ids),pauseEdge=chainEdges.find(e=>familyLabel(actor.brainGraph.nodes.find(n=>n.id===e.from)?.type)==='IMPULSE'&&familyLabel(actor.brainGraph.nodes.find(n=>n.id===e.to)?.type)==='REACTION')||chainEdges.find(e=>familyLabel(actor.brainGraph.nodes.find(n=>n.id===e.to)?.type)==='REACTION'),rewireEdge=chainEdges.find(e=>hotPatchRewireOptions(actor,e).length);overlay.innerHTML=`<div class="overlay-card"><p class="kicker">HOT PATCH</p><h3>МОЗГ НАГРЕВАЕТСЯ.</h3><p>Сейчас эта цепочка собирается сделать хуже. Один патч — потом продолжаем тот же разговор.</p><div class="chain">${chain}</div><div class="patch-grid">${repeat?`<button data-patch="repeat">REPEAT ×${repeat.p.count} → ×${Math.max(1,repeat.p.count-1)}</button>`:''}${impulse?`<button data-patch="impulse">${title(impulse.type)} ${impulse.p.weight} → ${Math.max(1,impulse.p.weight-1)}</button>`:''}${pauseEdge?'<button data-patch="pause">ВСТАВИТЬ ПАУЗУ</button>':''}${rewireEdge?'<button data-patch="rewire">СМЕНИТЬ СВЯЗЬ</button>':''}<button data-patch="skip">НИЧЕГО НЕ ТРОГАТЬ</button></div></div>`;overlay.hidden=false;$('[data-patch=repeat]')?.addEventListener('click',()=>controller.patch({kind:'reduce-repeat',actorId:bp.actorId,nodeId:repeat.id}));$('[data-patch=impulse]')?.addEventListener('click',()=>controller.patch({kind:'reduce-impulse',actorId:bp.actorId,nodeId:impulse.id}));$('[data-patch=pause]')?.addEventListener('click',()=>controller.patch({kind:'insert-pause',actorId:bp.actorId,edgeId:pauseEdge.id,nodeId:`pause-${controller.encounter.turn}-${bp.actorId}`}));$('[data-patch=rewire]')?.addEventListener('click',()=>showRewirePatch(bp,rewireEdge));$('[data-patch=skip]').addEventListener('click',()=>{controller.declinePatch();hideOverlay();if(mode==='auto')startAuto()})}
function showTrace(){const trace=controller?.encounter?.traces.at(-1);if(!trace)return;overlay.innerHTML=`<div class="overlay-card"><p class="kicker">TRACE</p><h3>ПОЧЕМУ ЭТО СЛУЧИЛОСЬ?</h3><div class="trace-list">TRIGGER: ${trace.trigger}\nPATH: ${trace.visitedNodes.join(' → ')}\nIMPULSE: ${trace.selectedImpulse}\nREACTION: ${trace.selectedReaction}\nLOOPS: ${trace.loops}\nMEMORY: ${(trace.memoryChanges||[]).map(m=>`${m.key} ${m.before}→${m.after}`).join(', ')||'—'}</div><button class="primary" id="close-overlay">ЗАКРЫТЬ</button></div>`;overlay.hidden=false;$('#close-overlay').onclick=hideOverlay}
function hideOverlay(){overlay.hidden=true;overlay.innerHTML=''}
function comparisonHtml(c){const fmt=v=>`${v>0?'+':''}${v}`;return `<small>БЫЛО / СТАЛО</small><strong>${c.sameScenario?'ТОТ ЖЕ СЦЕНАРИЙ':'СЦЕНАРИЙ ИЗМЕНИЛСЯ'}</strong><div class="compare-grid"><span>BRAIN ${fmt(c.metrics.brain)}</span><span>TENSION ${fmt(c.metrics.tension)}</span><span>CONTACT ${fmt(c.metrics.contact)}</span><span>ENERGY ${fmt(c.metrics.energy)}</span></div>`}
function showResult(result){show('result');$('#result-title').textContent=result.punchline;$('#result-cause').textContent=result.stageB.cause;$('#result-node').textContent=result.stageC.nodeType?title(result.stageC.nodeType):'—';if(!baselineEncounter){baselineEncounter=structuredClone(controller.encounter);replayTargetNodeId=result.stageC.nodeId||null;$('#comparison').hidden=true;$('#rerun').textContent='ИЗМЕНИТЬ ОДНУ ВЕЩЬ →'}else if(replayMode){const c=compareRuns(baselineEncounter,controller.encounter);$('#comparison').innerHTML=comparisonHtml(c);$('#comparison').hidden=false;$('#rerun').textContent='ЕЩЁ ОДИН ЭКСПЕРИМЕНТ →'}}
function prepareReplay(){replayMode=true;playerName=firstRunConfig?.playerName||playerName;syncPlayerName();currentCharacterId=firstRunConfig?.characterId||currentCharacterId;sharedAppearance={...(firstRunConfig?.sharedAppearance||sharedAppearance)};ownedAppearance=structuredClone(firstRunConfig?.ownedAppearance||ownedAppearance);appearanceColors=structuredClone(firstRunConfig?.appearanceColors||appearanceColors);opponentSeed=firstRunConfig.opponentSeed;opponentProfile=structuredClone(firstRunConfig.opponentProfile);restoreBrainSnapshot(firstRunConfig.brainGraph);controller=null;const targetNode=currentBrainGraph.nodes.find(n=>n.id===replayTargetNodeId);$('#replay-note').textContent=`КОНТРФАКТ: МЕНЯЕМ ТОЛЬКО «${title(targetNode?.type||'repeat')}». СОПЕРНИК ТОТ ЖЕ.`;show('brain')}
$('#player-name')?.addEventListener('input',e=>setPlayerName(e.target.value));$$('.character-switch [data-character]').forEach(b=>b.addEventListener('click',()=>chooseCharacter(b.dataset.character)));$$('[data-part]').forEach(b=>b.addEventListener('click',()=>toggleAppearance(b.dataset.part)));$('#appearance-reset').onclick=resetAppearance;$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b))}));$$('.bottom-nav button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.nav==='talk'&&!controller?.encounter)return;show(b.dataset.nav)}));$('#to-brain').onclick=()=>{resetActors();show('brain')};$('#to-setup').onclick=()=>show('setup');$('#brain-add-node').onclick=showNodeLibrary;$('#reroll-opponent').onclick=rerollOpponent;$('#play').onclick=()=>{if(!replayMode&&!firstRunConfig)firstRunConfig={brainGraph:brainSnapshot(),playerName:playerDisplayName(),characterId:currentCharacterId,sharedAppearance:{...sharedAppearance},ownedAppearance:structuredClone(ownedAppearance),appearanceColors:structuredClone(appearanceColors),mode,opponentSeed,opponentProfile:structuredClone(opponentProfile)};resetActors();makeController();controller.start({mode});show('talk');if(mode==='auto')startAuto()};$('#next-turn').onclick=()=>{if(mode==='auto'){autoTimer?stopAuto():startAuto()}else doNext()};$('#trace-btn').onclick=showTrace;$('#rerun').onclick=async()=>{if(!baselineEncounter)return;if(replayMode){baselineEncounter=null;firstRunConfig=null;replayTargetNodeId=null;replayMode=false;opponentSeed=explicitSeed||freshOpponentSeed();opponentProfile=createOpponentProfile(opponentSeed);await remountOpponent();controller=null;show('brain')}else prepareReplay()};overlay.addEventListener('click',e=>{if(e.target===overlay)hideOverlay()});window.addEventListener('resize',()=>{if(app.dataset.screen==='brain')requestAnimationFrame(drawBrainEdges)});
resetActors();syncPlayerName();syncCharacterSwitch();await mountCharacterAssets();renderScenarioCopy();show('person');
